UPDATE ip_pool_status
SET security_type = #{row.newSecurityType}
   ,updt_time = #{updateTime}
WHERE id = #{row.poolStatusId}
  AND is_deleted = 0
  AND audit_status = '20'
  AND security_type = #{row.oldSecurityType}

UPDATE ip_pool_status_crmw
SET security_type = #{row.newSecurityType}
   ,updt_time = #{updateTime}
WHERE id = #{row.poolStatusId}
  AND is_deleted = 0
  AND audit_status = '20'
  AND security_type = #{row.oldSecurityType}

UPDATE ip_adjust_log
SET security_type = #{securityType}
   ,updt_time = #{updateTime}
WHERE id = #{adjustLogId}
  AND is_deleted = 0
